mapper.update:
UPDATE case_mirror_outbox SET status = 'in_flight', lease_owner = #{owner},
  locked_until = #{leaseUntil,jdbcType=TIMESTAMP}, attempts = attempts + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE case_mirror_outbox SET status = 'succeeded', lease_owner = NULL,
  locked_until = NULL, last_error = NULL, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND lease_owner = #{owner}
